p("\u7814\u7a76\u59cb\u4e8e\u5bf9\u7a0b\u5e8f\u5207\u7247(Program Slicing)\u8fd9\u4e00\u7ecf\u5178\u7a0b\u5e8f\u5206\u6790\u6280\u672f\u7684\u7cfb\u7edf\u5b66\u4e60.\u7a0b\u5e8f\u5207\u7247\u6700\u65e9\u7531 Weiser \u4e8e 1984 \u5e74\u63d0\u51fa,\u5176\u6838\u5fc3\u601d\u60f3\u662f:\u7ed9\u5b9a\u4e00\u4e2a\u7a0b\u5e8f\u4e2d\u7684\u67d0\u4e2a\u8bed\u53e5(\u5373\u5207\u7247\u51c6\u5219 slicing criterion),\u627e\u51fa\u6240\u6709\u53ef\u80fd\u5f71\u54cd\u8be5\u8bed\u53e5\u503c\u7684\u7a0b\u5e8f\u8bed\u53e5\u96c6\u5408.\u8fd9\u4e2a\u65b9\u6cd5\u88ab\u5e7f\u6cdb\u7528\u4e8e\u8f6f\u4ef6\u8c03\u8bd5------\u7a0b\u5e8f\u5458\u770b\u5230\u4e00\u4e2a\u9519\u8bef\u8f93\u51fa,\u60f3\u77e5\u9053\u54ea\u4e9b\u4ee3\u7801\u5bfc\u81f4\u4e86\u5b83.")
